index 14484e060ea..7da98f2a8e6 100644
--- a/sql/field.h
+++ b/sql/field.h
@@ -1178,6 +1178,10 @@ class Field {
                       uint max_len [[maybe_unused]]) const {
     return cmp(a, b);
   }
+  virtual int cmp_prefix_key_rec(const uchar *a, const uchar *b,
